import{_ as p,a0 as o,w as l,s as r,ao as d,I as n,x as s,a1 as i,A as e}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const b=JSON.parse('{"title":"awk 系列：如何使用 awk 按模式筛选文本或字符串 | LCTT x X-CMD","titleTemplate":false,"description":"awk 系列：如何使用 awk 按模式筛选文本或字符串 | LCTT (awk) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"awk 系列：如何使用 awk 按模式筛选文本或字符串 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"awk 系列：如何使用 awk 按模式筛选文本或字符串 | LCTT (awk) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"awk/Part 3 - How to Use Awk to Filter Text or Strings Using Pattern Specific Actions","title":"awk 系列：如何使用 awk 按模式筛选文本或字符串","tag":"awk","desc":""},"relativePath":"awk/Part 3 - How to Use Awk to Filter Text or Strings Using Pattern Specific Actions.md","filePath":"[post].md"}'),k={name:"awk/Part 3 - How to Use Awk to Filter Text or Strings Using Pattern Specific Actions.md"};function w(g,t,c,u,h,m){const a=o("Link");return l(),r("div",null,[t[13]||(t[13]=d(`<h1 id="awk-系列-如何使用-awk-按模式筛选文本或字符串" tabindex="-1">awk 系列：如何使用 awk 按模式筛选文本或字符串 <a class="header-anchor" href="#awk-系列-如何使用-awk-按模式筛选文本或字符串" aria-label="Permalink to “awk 系列：如何使用 awk 按模式筛选文本或字符串”">​</a></h1><p><img src="http://www.tecmint.com/wp-content/uploads/2016/04/Use-Awk-to-Filter-Text-or-Strings-Using-Pattern.png" alt=""></p><p>作为 awk 命令系列的第三部分，这次我们将看一看如何基于用户定义的特定模式来筛选文本或字符串。</p><p>在筛选文本时，有时你可能想根据某个给定的条件或使用一个可被匹配的特定模式，去标记某个文件或数行字符串中的某几行。使用 awk 来完成这个任务是非常容易的，这也正是 awk 中可能对你有所帮助的几个功能之一。</p><p>让我们看一看下面这个例子，比方说你有一个写有你想要购买的食物的购物清单，其名称为 food_prices.list，它所含有的食物名称及相应的价格如下所示：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cat food_prices.list </span></span>
<span class="line"><span>No	Item_Name		Quantity	Price</span></span>
<span class="line"><span>1	Mangoes			   10		$2.45</span></span>
<span class="line"><span>2	Apples			   20		$1.50</span></span>
<span class="line"><span>3	Bananas			   5		$0.90</span></span>
<span class="line"><span>4	Pineapples		   10		$3.46</span></span>
<span class="line"><span>5	Oranges			   10		$0.78</span></span>
<span class="line"><span>6	Tomatoes		   5		$0.55</span></span>
<span class="line"><span>7	Onions			   5        $0.45</span></span></code></pre></div><p>然后，你想使用一个 <code>(*)</code> 符号去标记那些单价大于 $2 的食物，那么你可以通过运行下面的命令来达到此目的：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ awk &#39;/ *\\$[2-9]\\.[0-9][0-9] */ { print $1, $2, $3, $4, &quot;*&quot; ; } / *\\$[0-1]\\.[0-9][0-9] */ { print ; }&#39; food_prices.list</span></span></code></pre></div><p><img src="http://www.tecmint.com/wp-content/uploads/2016/04/Filter-and-Print-Text-Using-Awk.gif" alt=""></p><p><em>打印出单价大于 $2 的项目</em></p><p>从上面的输出你可以看到在含有 芒果（mangoes） 和菠萝（pineapples）的那行末尾都已经有了一个 <code>(*)</code> 标记。假如你检查它们的单价，你可以看到它们的单价的确超过了 $2 。</p><p>在这个例子中，我们已经使用了两个模式：</p><ul><li>第一个模式: <code>/ *\\$[2-9]\\.[0-9][0-9] */</code> 将会得到那些含有食物单价大于 $2 的行，</li><li>第二个模式: <code>/*\\$[0-1]\\.[0-9][0-9] */</code> 将查找那些食物单价小于 $2 的那些行。</li></ul><p>上面的命令具体做了什么呢？这个文件有四个字段，当模式一匹配到含有食物单价大于 $2 的行时，它便会输出所有的四个字段并在该行末尾加上一个 <code>(*)</code> 符号来作为标记。</p><p>第二个模式只是简单地输出其他含有食物单价小于 $2 的行，按照它们出现在输入文件 food_prices.list 中的样子。</p><p>这样你就可以使用模式来筛选出那些价格超过 $2 的食物项目，尽管上面的输出还有些问题，带有 <code>(*)</code> 符号的那些行并没有像其他行那样被格式化输出，这使得输出显得不够清晰。</p><p>我们在 awk 系列的第二部分中也看到了同样的问题，但我们可以使用下面的两种方式来解决：</p><p>1、可以像下面这样使用 printf 命令，但这样使用又长又无聊：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ awk &#39;/ *\\$[2-9]\\.[0-9][0-9] */ { printf &quot;%-10s %-10s %-10s %-10s\\n&quot;, $1, $2, $3, $4 &quot;*&quot; ; } / *\\$[0-1]\\.[0-9][0-9] */ { printf &quot;%-10s %-10s %-10s %-10s\\n&quot;, $1, $2, $3, $4; }&#39; food_prices.list</span></span></code></pre></div><p><img src="http://www.tecmint.com/wp-content/uploads/2016/04/Filter-and-Print-Items-Using-Awk-and-Printf.gif" alt=""></p><p><em>使用 Awk 和 Printf 来筛选和输出项目</em></p><p>2、 使用 <code>$0</code> 字段。Awk 使用变量 <strong>0</strong> 来存储整个输入行。对于上面的问题，这种方式非常方便，并且它还简单、快速：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ awk &#39;/ *\\$[2-9]\\.[0-9][0-9] */ { print $0 &quot;*&quot; ; } / *\\$[0-1]\\.[0-9][0-9] */ { print ; }&#39; food_prices.list</span></span></code></pre></div><p><img src="http://www.tecmint.com/wp-content/uploads/2016/04/Filter-and-Print-Items-Using-Awk-and-Variable.gif" alt=""></p><p><em>使用 Awk 和变量来筛选和输出项目</em></p><h3 id="结论" tabindex="-1">结论 <a class="header-anchor" href="#结论" aria-label="Permalink to “结论”">​</a></h3><p>这就是全部内容了，使用 awk 命令你便可以通过几种简单的方法去利用模式匹配来筛选文本，帮助你在一个文件中对文本或字符串的某些行做标记。</p><p>希望这篇文章对你有所帮助。记得阅读这个系列的下一部分，我们将关注在 awk 工具中使用比较运算符。</p><hr>`,29)),n("p",null,[t[1]||(t[1]=s("via: ",-1)),i(a,{href:"http://www.tecmint.com/awk-filter-text-or-string-using-patterns/"},{default:e(()=>[...t[0]||(t[0]=[s("http://www.tecmint.com/awk-filter-text-or-string-using-patterns/",-1)])]),_:1})]),n("p",null,[t[5]||(t[5]=s("作者：",-1)),i(a,{href:"http://www.tecmint.com/author/aaronkili/"},{default:e(()=>[...t[2]||(t[2]=[s("Aaron Kili",-1)])]),_:1}),t[6]||(t[6]=s(" 译者：",-1)),i(a,{href:"https://github.com/FSSlc"},{default:e(()=>[...t[3]||(t[3]=[s("FSSlc",-1)])]),_:1}),t[7]||(t[7]=s(" 校对：",-1)),i(a,{href:"https://github.com/wxy"},{default:e(()=>[...t[4]||(t[4]=[s("wxy",-1)])]),_:1})]),n("p",null,[t[10]||(t[10]=s("本文由 ",-1)),i(a,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>[...t[8]||(t[8]=[s("LCTT",-1)])]),_:1}),t[11]||(t[11]=s(" 原创编译，",-1)),i(a,{href:"https://linux.cn/"},{default:e(()=>[...t[9]||(t[9]=[s("Linux中国",-1)])]),_:1}),t[12]||(t[12]=s(" 荣誉推出",-1))])])}const T=p(k,[["render",w]]);export{b as __pageData,T as default};
